long long modExp(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    long long p, k;
    cin >> p >> k;
    const long long pcon = 1000000007;
    vector<long long> invArr(1000003, 0);
    invArr[1] = 1;
    for (long long i = 2; i < 1000003; ++i) {
        long long a = pcon / i;
        long long b = pcon % i;
        long long c = (a * (pcon - invArr[b])) % pcon;
        invArr[i] = c;
    }
    long long total = 0;
    if (k == 0) {
        total = 1;
        for (long long i = 0; i < p - 1; ++i) {
            total = (total * p) % pcon;
        }
    } else {
        long long product = 1, firstFlag = 0, indexVal = 0;
        for (long long i = 1; i < p; ++i) {
            product = (product * k) % p;
            if ((product % p) == 1 && firstFlag == 0) {
                indexVal = i;
                firstFlag = 1;
            }
        }
        total = 1;
        long long t = (p - 1) / indexVal;
