            for (long long i = 1; i <= t; ++i) {
                long long temp = (invArr[i] * (t - i + 1)) % pcon;
                temp = (temp * t) % pcon;
                temp = (temp * indexVal) % pcon;
                sumVal = (sumVal + temp) % pcon;
            }
            total = (total + sumVal) % pcon;
        }
    }
    cout << total;
}
